import itertools


class ArrangementCalculator:
    def __init__(self, datas):
        self._datas = datas

    @property
    def datas(self):
        return list(self._datas)

    def generate_permutations(self, m=None):
        if m is None:
            m = len(self._datas)
        return [list(permutation) for permutation in itertools.permutations(self._datas, m)]

    def count(self, m=None):
        if m is None or self._datas is None or m > len(self._datas):
            m = len(self._datas)
        return self._factorial(len(self._datas)) // self._factorial(len(self._datas) - m)

    def count_all(self, n=None):
        if n is None:
            n = len(self._datas)
        return sum(self.count(i) for i in range(1, n + 1))

    def select(self, m=None):
        if m is None:
            m = len(self._datas)
        return self.generate_permutations(m)

    def select_all(self):
        n = len(self._datas)
        return [item for i in range(1, n + 1) for item in self.generate_permutations(i)]

    @classmethod
    def _factorial(cls, n):
        return cls.factorial(n)

    @staticmethod
    def factorial(n):
        if n <= 1:
            return 1
        return n * ArrangementCalculator.factorial(n - 1)

    @staticmethod
    def count(n, m=None):
        if m is None or n == m:
            return ArrangementCalculator.factorial(n)
        else:
            return ArrangementCalculator.factorial(n) // ArrangementCalculator.factorial(n - m)
